-- Replaces the 001 seed's placeholder /images/products/*.jpg paths (which point to no
-- real files) with self-contained inline SVG placeholders, so the catalog has a visible
-- image per product with no external image hosting/static-file serving needed yet.
-- Still placeholder art, not real product photography — swap before going live.
--
-- The inline data URIs run ~650-700 chars, over the original VARCHAR(512) — widen first.
ALTER TABLE shop.products ALTER COLUMN image_url TYPE TEXT;

